// Generate .claude/skills/ copies and .agents/harness/bin/ shims, and run sync-hooks for .claude/settings.json and .agents/hooks.json.
// Usage: sync-settings.swift [--check]   --check writes nothing and exits 1 if any generated file is out of date.
// hooks.json: {"events": {"pre-shell": ["hooks/x.swift", ...], "pre-edit": [...], ...}}
import Foundation

// MARK: - Wiring

let environment = ProcessInfo.processInfo.environment
let proj = URL(fileURLWithPath: environment["CLAUDE_PROJECT_DIR"] ?? FileManager.default.currentDirectoryPath)
let check = CommandLine.arguments.contains("--check")

guard let data = try? Data(contentsOf: proj.appendingPathComponent(".agents/harness/hooks.json")),
    let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
    let events = json["events"] as? [String: [String]]
else {
    FileHandle.standardError.write(Data("cannot read .agents/harness/hooks.json\n".utf8))
    exit(2)
}

var stale = false

// Skills: .agents/harness/skills/<name>/ is the source; Claude Code reads .claude/skills/<name>/ (copies).
let fm = FileManager.default
let skillsSrc = proj.appendingPathComponent(".agents/harness/skills")
let skillsDst = proj.appendingPathComponent(".claude/skills")
for name in ((try? fm.contentsOfDirectory(atPath: skillsSrc.path)) ?? []).sorted() where !name.hasPrefix(".") {
    let enumerator = fm.enumerator(atPath: skillsSrc.appendingPathComponent(name).path)
    while let rel = enumerator?.nextObject() as? String {
        let from = skillsSrc.appendingPathComponent("\(name)/\(rel)")
        let to = skillsDst.appendingPathComponent("\(name)/\(rel)")
        var isDir: ObjCBool = false
        guard fm.fileExists(atPath: from.path, isDirectory: &isDir), !isDir.boolValue, !rel.hasSuffix(".DS_Store")
        else { continue }
        if check {
            if (try? Data(contentsOf: to)) != (try? Data(contentsOf: from)) {
                FileHandle.standardError.write(Data(".claude/skills/\(name)/\(rel) is out of date\n".utf8))
                stale = true
            }
        } else {
            try fm.createDirectory(at: to.deletingLastPathComponent(), withIntermediateDirectories: true)
            // the old copy may not exist yet, so a failed removal is expected; the copy below reports any real error
            try? fm.removeItem(at: to)
            try fm.copyItem(at: from, to: to)
        }
    }
}
// Entry points: .agents/harness/bin/<name> runs hooks/<name>.swift or tools/<name>.swift as a binary that `swiftc` built into
// .agents/harness/.cache/bin the first time, and rebuilds whenever the source is newer (about 0.02 s a call, against 0.4 s for the
// Swift interpreter). Only the Swift toolchain is needed. Generated; do not edit.
// A hook's result is its exit status (2 blocks) and its output. If the build fails, the shim runs the source under
// `swift`; if a hook's binary exits with anything but 0 or 2 (a crash), the cache is dropped and the source runs under
// `swift` with the same input, so a broken binary cannot quietly turn a guard into a no-op.
// .agents/harness/bin/build.sh builds every binary ahead of time, four at once.
let binDir = proj.appendingPathComponent(".agents/harness/bin")
let shimMark = "# Generated by .agents/harness/hooks/sync-settings.swift. Do not edit."
var wantedShims: [String: String] = [:]
let hookNames = Set(
    events.values.flatMap { $0 }.map { String(($0 as NSString).lastPathComponent.dropLast(".swift".count)) })
for sub in ["hooks", "tools"] {
    let subDir = proj.appendingPathComponent(".agents/harness/\(sub)").path
    for file in ((try? fm.contentsOfDirectory(atPath: subDir)) ?? []).sorted() where file.hasSuffix(".swift") {
        let name = String(file.dropLast(".swift".count))
        if wantedShims[name] != nil {
            let message = ".agents/harness/bin/\(name): both hooks/ and tools/ have \(file)\n"
            FileHandle.standardError.write(Data(message.utf8))
            exit(2)
        }
        let find = """
            root="$(cd "$(dirname "$0")/.." && pwd)"
            export CLAUDE_PROJECT_DIR="$(cd "$root/../.." && pwd)"
            f="$root/\(sub)/\(file)"
            bin="$root/.cache/bin/\(name)"
            if [ ! -x "$bin" ] || [ "$f" -nt "$bin" ]; then
                mkdir -p "$root/.cache/bin"
                if swiftc -Onone -gnone -o "$bin.$$" "$f" 2>/dev/null; then mv -f "$bin.$$" "$bin"
                else rm -f "$bin.$$"; exec swift "$f" "$@"; fi
            fi

            """
        if hookNames.contains(name) {
            // A hook: stdin is the harness's JSON. Run the cached binary; a status other than 0 or 2 means it crashed, so the source runs instead.
            wantedShims[name] = """
                \u{23}!/bin/sh
                \(shimMark)
                \(find)in="$(mktemp)"; err="$(mktemp)"; cat > "$in"
                out="$("$bin" "$@" < "$in" 2> "$err")"; rc=$?
                if [ "$rc" -eq 0 ] || [ "$rc" -eq 2 ]; then
                    [ -n "$out" ] && printf '%s\\n' "$out"
                    cat "$err" >&2; rm -f "$in" "$err"; exit "$rc"
                fi
                rm -f "$bin"
                out="$(swift "$f" "$@" < "$in")"; rc=$?
                [ -n "$out" ] && printf '%s\\n' "$out"
                rm -f "$in" "$err"; exit "$rc"

                """
        } else {
            // A tool: it may read a terminal or nothing at all, so stdin is passed straight through.
            wantedShims[name] = """
                \u{23}!/bin/sh
                \(shimMark)
                \(find)exec "$bin" "$@"

                """
        }
    }
}
wantedShims["build.sh"] = """
    \u{23}!/bin/sh
    \(shimMark)
    \u{23} Builds every hook and tool into .agents/harness/.cache/bin, four at a time, so the first call of each is fast.
    \u{23} A binary newer than its source is left alone. Usage: .agents/harness/bin/build.sh
    root="$(cd "$(dirname "$0")/.." && pwd)"
    mkdir -p "$root/.cache/bin"
    n=0
    for f in "$root"/hooks/*.swift "$root"/tools/*.swift; do
        name="$(basename "$f" .swift)"; bin="$root/.cache/bin/$name"
        if [ -x "$bin" ] && [ ! "$f" -nt "$bin" ]; then continue; fi
        (
            err="$(swiftc -Onone -gnone -o "$bin.$$" "$f" 2>&1)"
            if [ $? -eq 0 ]; then mv -f "$bin.$$" "$bin"
            else rm -f "$bin.$$"; echo "build.sh: $name did not compile" >&2; printf '%s\\n' "$err" >&2; fi
        ) &
        n=$((n + 1)); if [ $((n % 4)) -eq 0 ]; then wait; fi
    done
    wait

    """
if !check { try fm.createDirectory(at: binDir, withIntermediateDirectories: true) }
for (name, body) in wantedShims.sorted(by: { $0.key < $1.key }) {
    let path = binDir.appendingPathComponent(name)
    if check {
        if (try? String(contentsOf: path, encoding: .utf8)) != body {
            FileHandle.standardError.write(Data(".agents/harness/bin/\(name) is out of date\n".utf8))
            stale = true
        }
    } else if (try? String(contentsOf: path, encoding: .utf8)) != body {
        try body.write(to: path, atomically: true, encoding: .utf8)
        try fm.setAttributes([.posixPermissions: 0o755], ofItemAtPath: path.path)
    }
}
for name in ((try? fm.contentsOfDirectory(atPath: binDir.path)) ?? []).sorted()
where wantedShims[name] == nil && !name.hasPrefix(".") {
    let path = binDir.appendingPathComponent(name)
    // only generated files are touched, so a file we did not write is left alone
    guard (try? String(contentsOf: path, encoding: .utf8))?.contains(shimMark) == true else { continue }
    if check {
        FileHandle.standardError.write(Data(".agents/harness/bin/\(name) has no source script\n".utf8))
        stale = true
    } else {
        try fm.removeItem(at: path)
    }
}

let syncHooks = proj.appendingPathComponent(".agents/harness/bin/sync-hooks")
if fm.fileExists(atPath: syncHooks.path) {
    let p = Process()
    p.executableURL = syncHooks
    p.arguments = check ? ["--check"] : []
    var env = environment
    env["CLAUDE_PROJECT_DIR"] = proj.path
    p.environment = env
    try p.run()
    p.waitUntilExit()
    if p.terminationStatus != 0 { stale = true }
}

exit(stale ? 1 : 0)
